def trace(header, steps, variables):
    parts = [header, f'ScenarioLength == {len(steps)}\nScenarioNext ==\n    \\/ (pc = ScenarioLength /\\ UNCHANGED {variables})\n']
    parts.extend(f"    \\/ (pc = {i} /\\ ({action}) /\\ pc' = pc + 1)\n" for i, (action, _) in enumerate(steps))
    parts.append('ScenarioAssertions ==\n    /\\ pc \\in 0..ScenarioLength\n')
    parts.extend(f'    /\\ (pc = {i+1} => ({check}))\n' for i, (_, check) in enumerate(steps) if check)
    parts.append(f'ScenarioSpec == ScenarioInit /\\ [][ScenarioNext]_{variables} /\\ WF_{variables}(ScenarioNext)\nCompletes == <>(pc = ScenarioLength)\n=============================================================================\n')
    return ''.join(parts)

(ROOT / 'EntityScenarios.tla').write_text(trace(ENTITY_HEADER, ENTITY_STEPS, 'scenarioVars'))
parts = [SET_HEADER, 'ScenarioLength == CASE ' + '\n    [] '.join(f'Scenario="{name}" -> {len(steps)}' for name, steps in SET_CASES.items()) + '\n', 'ScenarioNext ==\n    \\/ (pc = ScenarioLength /\\ UNCHANGED scenarioVars)\n']
for name, steps in SET_CASES.items():
    parts.append(f'    \\/ /\\ Scenario = "{name}"\n       /\\ \\/ ' + '\n          \\/ '.join(f"(pc = {i} /\\ ({action}) /\\ pc' = pc + 1)" for i, (action, _) in enumerate(steps)) + '\n')
parts.append('ScenarioAssertions ==\n    /\\ pc \\in 0..ScenarioLength\n')
for name, steps in SET_CASES.items():
    parts.extend(f'    /\\ (Scenario = "{name}" /\\ pc = {i+1} => ({check}))\n' for i, (_, check) in enumerate(steps) if check)
parts.append('ScenarioSpec == ScenarioInit /\\ [][ScenarioNext]_scenarioVars /\\ WF_scenarioVars(ScenarioNext)\nCompletes == <>(pc = ScenarioLength)\n=============================================================================\n')
(ROOT / 'SetScenarios.tla').write_text(''.join(parts))
for name in SET_CASES:
    cfg = (ROOT / 'configs' / 'SetTransactions.cfg').read_text().replace('TLC_MODULE SetTransactions', 'TLC_MODULE SetScenarios').replace('SPECIFICATION TransactionSpec', 'SPECIFICATION ScenarioSpec').replace('VLANs = {1, 10}', 'VLANs = {1, 10, 20}').replace('INVARIANTS TypeOK', f'    Scenario = "{name}"\nINVARIANTS TypeOK').replace(' SetRequestsComplete', ' Completes')
    if name in ('BitmapPorts', 'AbsentDestroy'):
        cfg = cfg.replace('Ports = {1}', 'Ports = {1, 2}')
    (ROOT / 'configs' / f'Set{name}.cfg').write_text(cfg + 'INVARIANT ScenarioAssertions\n')
